//! Bounded Node/V8 `Math.hypot` diagnostic characterization.
//!
//! The committed corpus is generated by
//! `scripts/rust-parity/dump-js-hypot.ts`. Finite results compare by ordered
//! binary64 ULP distance, infinities by classification and sign, and NaNs by
//! classification because their payload bits are not portable across runtimes.

use irregular_nesting_native::js_number::js_math::hypot;
use serde::Deserialize;

const VECTORS_JSON: &str = include_str!("vectors/js-hypot.json");

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Meta {
    area: String,
    node_version: String,
    v8_version: String,
    seed: u32,
    source_sha256: String,
    corpus_sha256: String,
    vector_count: usize,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct HypotVector {
    x_bits: String,
    y_bits: String,
    expected_bits: String,
    #[serde(rename = "expectedIsNaN")]
    expected_is_nan: bool,
}

#[derive(Deserialize)]
struct VectorFile {
    meta: Meta,
    cases: Vec<HypotVector>,
}

fn bits(hex: &str) -> u64 {
    u64::from_str_radix(hex, 16)
        .unwrap_or_else(|error| panic!("invalid binary64 bit pattern {hex:?}: {error}"))
}

fn ordered_bits(value: f64) -> u64 {
    let bits = value.to_bits();
    if bits & (1_u64 << 63) == 0 {
        bits | (1_u64 << 63)
    } else {
        !bits
    }
}

fn ulp_distance(first: f64, second: f64) -> u64 {
    ordered_bits(first).abs_diff(ordered_bits(second))
}

#[test]
fn standard_hypot_stays_within_the_documented_node_v8_envelope() {
    let file: VectorFile =
        serde_json::from_str(VECTORS_JSON).expect("tests/vectors/js-hypot.json must parse");

    assert_eq!(file.meta.area, "js-hypot");
    assert!(file.meta.node_version.starts_with('v'));
    assert!(!file.meta.v8_version.is_empty());
    assert_eq!(file.meta.seed, 0x5eed_c0de);
    assert_eq!(file.meta.source_sha256.len(), 64);
    assert_eq!(file.meta.corpus_sha256.len(), 64);
    assert_eq!(file.meta.vector_count, 21_696);
    assert_eq!(file.cases.len(), 21_696);

    let mut classification_mismatches = 0;
    let mut exact_matches = 0;
    let mut nan_matches = 0;
    let mut ulp_mismatches = 0;
    let mut one_ulp_mismatches = 0;
    let mut two_ulp_mismatches = 0;
    let mut maximum_ulp_distance = 0;
    let mut finite_or_infinite_cases = 0;

    for (index, vector) in file.cases.iter().enumerate() {
        let x = f64::from_bits(bits(&vector.x_bits));
        let y = f64::from_bits(bits(&vector.y_bits));
        let expected = f64::from_bits(bits(&vector.expected_bits));
        let actual = hypot(x, y);

        if vector.expected_is_nan {
            if actual.is_nan() {
                nan_matches += 1;
            } else {
                classification_mismatches += 1;
                eprintln!("case {index}: expected NaN, got {actual:?}");
            }
            continue;
        }

        finite_or_infinite_cases += 1;
        if expected.is_infinite() {
            if actual.is_infinite() && actual.is_sign_positive() == expected.is_sign_positive() {
                exact_matches += 1;
            } else {
                classification_mismatches += 1;
                eprintln!("case {index}: expected infinity {expected:?}, got {actual:?}");
            }
            continue;
        }

        if !actual.is_finite() {
            classification_mismatches += 1;
            eprintln!("case {index}: expected finite {expected:?}, got {actual:?}");
            continue;
        }

        let distance = ulp_distance(actual, expected);
        maximum_ulp_distance = maximum_ulp_distance.max(distance);
        if distance == 0 {
            exact_matches += 1;
        } else {
            ulp_mismatches += 1;
            match distance {
                1 => one_ulp_mismatches += 1,
                2 => two_ulp_mismatches += 1,
                _ => {}
            }
        }
    }

    println!(
        "Node/V8 hypot characterization: exact_non_nan_matches={}, nan_matches={}, ulp_mismatches={}, one_ulp_mismatches={}, two_ulp_mismatches={}, maximum_ulp_distance={}, classification_mismatches={}",
        exact_matches,
        nan_matches,
        ulp_mismatches,
        one_ulp_mismatches,
        two_ulp_mismatches,
        maximum_ulp_distance,
        classification_mismatches,
    );

    assert_eq!(classification_mismatches, 0);
    assert!(maximum_ulp_distance <= 2);
    assert_eq!(exact_matches + ulp_mismatches, finite_or_infinite_cases);
}
